#include "fstr/external_lut.hpp"
#include "fstr/color.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
int main(int argc,char** argv){try{if(argc!=8)throw std::invalid_argument("Usage: width height input.rgba32f output.rgba32f LUT-path amount mix");auto number=[](const char* p){std::size_t n=0;auto x=std::stod(p,&n);if(n!=std::string(p).size())throw std::invalid_argument("Invalid number");return x;};const auto w=std::stoul(argv[1]),h=std::stoul(argv[2]);if(!w||!h||w>16384||h>16384||w>8388608/h)throw std::invalid_argument("Frame budget");std::vector<float> input(w*h*4);if(std::filesystem::file_size(argv[3])!=input.size()*sizeof(float))throw std::invalid_argument("Frame size");std::ifstream f(argv[3],std::ios::binary);f.read(reinterpret_cast<char*>(input.data()),std::streamsize(input.size()*sizeof(float)));if(!f)throw std::runtime_error("Frame read failed");auto external=fstr::load_external_lut(argv[5]);fstr::ColorSettings s;s.look=external.look;s.look_amount=number(argv[6]);s.mix=number(argv[7]);s.grade.natural_contrast=true;auto out=fstr::render_color({{input.data(),input.size(),w,h,w*4},0},s,{});if(out.status!=fstr::Status::Ok)throw std::runtime_error("Frame processing failed");std::ofstream dst(argv[4],std::ios::binary);dst.write(reinterpret_cast<const char*>(out.rgba.data()),std::streamsize(out.rgba.size()*sizeof(float)));dst.close();if(!dst)throw std::runtime_error("Frame write failed");std::cout<<"PASS native external LUT reference\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
